function validateReplyMessage(message) {
  for (const key of ['messageId', 'threadId', 'from']) if (typeof message?.[key] !== 'string' || message[key].trim() === '') throw new Error('Incoming Gmail message is missing ' + key + '.');
  if (typeof message.subject !== 'string' || typeof message.body !== 'string' || /[\r\n]/.test(message.from + message.subject)) throw new Error('Gmail subject, sender and body fields are invalid.');
  return { messageId: message.messageId, threadId: message.threadId, from: message.from, subject: message.subject, body: message.body };
}


