function validateReplyDecision(completion) {
  if (!completion || typeof completion !== 'object' || Array.isArray(completion) || typeof completion.needsReply !== 'boolean') throw new Error('The assessment must contain a boolean needsReply.');
  return completion.needsReply;
}


