function prepareReplyDraft(message, completion) {
  if (typeof completion !== 'string' || completion.trim() === '') throw new Error('The reply model returned no draft text.');
  const escape = text => text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
